const PW = 4.0, PH = 4.2, LEAN = 0.95, TOK = 8, GAP = 0.05, PUSH = 0.012;

/* ---- tilt so the camera shear reproduces the printed parallelogram -------- */
const KSH = Math.cos(Math.PI / 4) * 0.5;      // shear coefficient (45°, 0.5)
const CZ  = -LEAN / KSH;                      // world z of the plane's top edge
const BY  = PH / 2 + KSH * CZ;                // world y of the plane's top edge
const LEN = Math.hypot(BY, CZ);

const root = new THREE.Group();
root.rotation.x = Math.atan2(CZ, BY);
root.scale.set(1, LEN / (PH / 2), 1);
scene.add(root);

