const PANEL_STATE = {
  a: { n: 0, off: false, orig: true }, b: { n: 2, off: false, orig: false },
  c: { n: 2, off: true, orig: false }, d: { n: 1, off: false, orig: false },
  e: { n: 1, off: true, orig: false }, f: { n: 0, off: false, orig: false }
};
const curN = () => N_OF[state.nIdx];
function panelId() {
