const elWS = document.getElementById('windowSize');
const elWSV = document.getElementById('wsVal');
const btnReg = document.getElementById('btnReg');
const btnOff = document.getElementById('btnOff');

function syncUI() {
  elWS.value = String(state.nIdx);
  elWSV.textContent = curN() + '×' + curN();
