function tick(now) {
  requestAnimationFrame(tick);
  if (phase === 'close') {
    const u = Math.min(1, (now - t0) / 160);
    gv = gStart * (1 - ease(u));
    updateTiles(gv);
    if (u >= 1) {
      if (pending) { doBuild(pending.N, pending.off); pending = null; }
      gv = 0; updateTiles(0);
