const tokenMat = new THREE.LineBasicMaterial({ color: 0x3B3B3B, transparent: true, opacity: 0.6 });
const hiMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.18, depthWrite: false });
const dotMat = new THREE.PointsMaterial({ color: 0xFF6A00, size: 8, sizeAttenuation: false, transparent: true, opacity: 0.9, depthTest: false });

/* ---- state --------------------------------------------------------------- */
const state = { nIdx: 2, offset: false, grid: true, sel: null, curN: 4, curOff: false };
const N_OF = [1, 2, 4];
const curN = () => N_OF[state.nIdx];

/* ---- partition maths ----------------------------------------------------- */
function boundariesFor(N, off) {
  if (N <= 1) return [0, 1];
  const b = [];
  if (!off) { for (let i = 0; i <= N; i++) b.push(i / N); return b; }
  b.push(0);
  for (let i = 0; i < N; i++) b.push((2 * i + 1) / (2 * N));
  b.push(1);
  return b;
}
function winIndex(bs, c) {
  for (let k = 0; k < bs.length - 1; k++) if (c >= bs[k] && c < bs[k + 1]) return k;
  return bs.length - 2;
}
function computeMarks(N, off) {
  const m = new Set();
  if (!off || N <= 1) return m;
  const reg = boundariesFor(N, false), ofs = boundariesFor(N, true);
  const c = i => (i + 0.5) / TOK;
  for (let j = 0; j < TOK; j++) for (let i = 0; i < TOK - 1; i++) {
    if (winIndex(reg, c(i)) !== winIndex(reg, c(i + 1)) && winIndex(ofs, c(i)) === winIndex(ofs, c(i + 1))) {
      m.add(i + ',' + j); m.add((i + 1) + ',' + j);
    }
  }
  for (let i = 0; i < TOK; i++) for (let j = 0; j < TOK - 1; j++) {
    if (winIndex(reg, c(j)) !== winIndex(reg, c(j + 1)) && winIndex(ofs, c(j)) === winIndex(ofs, c(j + 1))) {
      m.add(i + ',' + j); m.add(i + ',' + (j + 1));
    }
  }
  return m;
}

/* ---- tiles --------------------------------------------------------------- */
const tiles = [];
const selInfo = document.getElementById('selInfo');

function disposeDeep(o) {
  o.traverse(c => {
    c.geometry?.dispose?.();
    const m = c.material;
    if (m && m.userData && m.userData.perTile) m.dispose();
  });
}
function clearSelection(quiet) {
  if (state.sel) {
    const t = state.sel;
    t.hi.visible = false;
    t.bord.material.color.setHex(0x111111);
    if (t.attn) { t.group.remove(t.attn); t.attn.geometry.dispose(); t.attn.material.dispose(); t.attn = null; }
    state.sel = null;
  }
  for (const o of tiles) o.mesh.material.color.setHex(0xffffff);
  if (!quiet && selInfo) selInfo.textContent = 'Click a tile to compute self-attention inside that window.';
}

function doBuild(N, off) {
  clearSelection(true);
  for (const t of tiles) { root.remove(t.group); disposeDeep(t.group); }
  tiles.length = 0;

  const bs = boundariesFor(N, off);
  const marks = computeMarks(N, off);

  for (let j = 0; j < bs.length - 1; j++) for (let i = 0; i < bs.length - 1; i++) {
    const u0 = bs[i], u1 = bs[i + 1], v0 = bs[j], v1 = bs[j + 1];
    const grp = new THREE.Group();

    // thick black outline: a backing quad slightly larger than the tile
    const bmat = new THREE.MeshBasicMaterial({ color: 0x111111 });
    bmat.userData.perTile = true;
    const bord = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), bmat);
    bord.position.z = -0.004;
    grp.add(bord);

    const geo = new THREE.PlaneGeometry(1, 1);
    geo.setAttribute('uv', new THREE.Float32BufferAttribute([u0, v1, u1, v1, u0, v0, u1, v0], 2));
    const mat = new THREE.MeshBasicMaterial({ map: muralTex, side: THREE.DoubleSide });
    mat.userData.perTile = true;
    const mesh = new THREE.Mesh(geo, mat);
    grp.add(mesh);

    // token grid inside this tile
    const seg = [];
    for (let k = 1; k < TOK; k++) {
      const u = k / TOK;
      if (u > u0 + 1e-6 && u < u1 - 1e-6) {
        const x = (u - u0) / (u1 - u0) - 0.5;
        seg.push(x, -0.5, 0.004, x, 0.5, 0.004);
      }
      const v = k / TOK;
      if (v > v0 + 1e-6 && v < v1 - 1e-6) {
        const y = (v - v0) / (v1 - v0) - 0.5;
        seg.push(-0.5, y, 0.004, 0.5, y, 0.004);
      }
    }
    let tok = null;
    if (seg.length) {
      const tg = new THREE.BufferGeometry();
      tg.setAttribute('position', new THREE.Float32BufferAttribute(seg, 3));
      tok = new THREE.LineSegments(tg, tokenMat);
      tok.renderOrder = 2; tok.visible = state.grid; grp.add(tok);
    }

    const hi = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), hiMat);
    hi.position.z = 0.008; hi.renderOrder = 4; hi.visible = false; grp.add(hi);

    // shifted-membership markers
    const dp = [];
    for (let ti = 0; ti < TOK; ti++) for (let tj = 0; tj < TOK; tj++) {
      const uc = (ti + 0.5) / TOK, vc = (tj + 0.5) / TOK;
      if (uc > u0 && uc < u1 && vc > v0 && vc < v1 && marks.has(ti + ',' + tj)) {
        dp.push((uc - u0) / (u1 - u0) - 0.5, (vc - v0) / (v1 - v0) - 0.5, 0.012);
      }
    }
    if (dp.length) {
      const dg = new THREE.BufferGeometry();
      dg.setAttribute('position', new THREE.Float32BufferAttribute(dp, 3));
      const pts = new THREE.Points(dg, dotMat);
      pts.renderOrder = 6; grp.add(pts);
    }

    root.add(grp);
    tiles.push({
      group: grp, mesh, bord, hi, tok, attn: null,
      u0, u1, v0, v1,
      w: (u1 - u0) * PW, h: (v1 - v0) * PH,
      cx: ((u0 + u1) / 2 - 0.5) * PW, cy: ((v0 + v1) / 2 - 0.5) * PH,
      col: i, row: j
    });
  }
  state.curN = N; state.curOff = off;
}

function updateTiles(gv) {
  for (const t of tiles) {
    const w = Math.max(0.03, t.w - GAP * gv);
    const h = Math.max(0.03, t.h - GAP * gv);
    t.group.scale.set(w, h, 1);
    t.group.position.set(t.cx * (1 + PUSH * gv), t.cy * (1 + PUSH * gv), 0);
    const bb = (t === state.sel) ? 0.034 : BORD;
    t.bord.scale.set(1 + 2 * bb / w, 1 + 2 * bb / h, 1);
  }
}
function applyGridVisibility() {
  for (const t of tiles) if (t.tok) t.tok.visible = state.grid;
}

/* ---- selection + attention ---------------------------------------------- */
function selectTile(t) {
  clearSelection(true);
  state.sel = t;
  t.hi.visible = true;
  t.bord.material.color.setHex(0xFFD24A);
  for (const o of tiles) o.mesh.material.color.setHex(o === t ? 0xffffff : 0x9a9a9a);

  const xs = [], ys = [];
  for (let i = 0; i < TOK; i++) {
    const u = (i + 0.5) / TOK;
    if (u > t.u0 && u < t.u1) xs.push((u - t.u0) / (t.u1 - t.u0) - 0.5);
    const v = (i + 0.5) / TOK;
    if (v > t.v0 && v < t.v1) ys.push((v - t.v0) / (t.v1 - t.v0) - 0.5);
  }
  const P = [];
  for (const y of ys) for (const x of xs) P.push([x, y]);
  const pos = [];
  for (let a = 0; a < P.length; a++) for (let b = a + 1; b < P.length; b++) {
    pos.push(P[a][0], P[a][1], 0.009, P[b][0], P[b][1], 0.009);
  }
  const pairs = P.length * (P.length - 1) / 2;
  const op = pairs <= 50 ? 0.32 : pairs <= 200 ? 0.2 : pairs <= 700 ? 0.11 : 0.06;
  const gm = new THREE.BufferGeometry();
  gm.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  const mm = new THREE.LineBasicMaterial({ color: 0x1E6FE0, transparent: true, opacity: op, depthTest: false });
  mm.userData.perTile = true;
  const ln = new THREE.LineSegments(gm, mm);
  ln.renderOrder = 7;
  t.group.add(ln); t.attn = ln;
  updateTiles(gv);

  selInfo.innerHTML = `Selected window: <b>${xs.length}×${ys.length}</b> tokens → <b>${pairs}</b> attention pairs.
    Every line stops at the white gap — neighbouring windows never exchange information in this layer.`;
  showPopup('Self-attention inside one window',
    `This window holds ${P.length} tokens, so attention costs ${pairs} pairs. ` +
    `With ${tiles.length} windows the total cost grows linearly in the number of windows instead of quadratically in all ${TOK * TOK} tokens.`);
}

/* ---- ellipsis dots (· · ·) ---------------------------------------------- */
const MIDX = LEAN / 2;   // screen-space centre of the sheared plane at mid height
const ellipMat = new THREE.MeshBasicMaterial({ color: 0x222222 });
const ellipMeshes = [];
for (const side of [-1, 1]) {
  for (let k = 0; k < 3; k++) {
    const sp = new THREE.Mesh(new THREE.SphereGeometry(0.06, 16, 12), ellipMat);
    sp.position.set(MIDX + side * (2.35 + 0.24 * k), 0, 0);
    sp.userData.dir = side;
    scene.add(sp);
    ellipMeshes.push(sp);
  }
}

/* ---- initial build, then camera, then labels ----------------------------- */
let gv = 1;
doBuild(4, false);
updateTiles(gv);

setCameraView({ projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0, heightFraction: 0.68 });

const letterLbl = addLabel('b)', new THREE.Vector3(-1.98, 2.46, 0), { fontSize: '21px' });
const capLbl = addLabel('4×4 windows', new THREE.Vector3(MIDX, -2.62, 0), { fontSize: '17px' });

/* ---- panel bookkeeping --------------------------------------------------- */
const CAPTION = {
  a: 'Original image', b: '4×4 windows', c: '4×4 offset windows',
  d: '2×2 windows', e: '2×2 offset windows', f: '1×1 window'
};
const PANEL_ORDER = ['a', 'b', 'c', 'd', 'e', 'f'];
const PANEL_STATE = {
  a: { n: 0, off: false, grid: false }, b: { n: 2, off: false, grid: true },
  c: { n: 2, off: true, grid: true }, d: { n: 1, off: false, grid: true },
  e: { n: 1, off: true, grid: true }, f: { n: 0, off: false, grid: true }
};
function panelId() {
  const N = curN();
  if (N === 1) return state.grid ? 'f' : 'a';
  if (N === 4) return state.offset ? 'c' : 'b';
  return state.offset ? 'e' : 'd';
}

const elWS = document.getElementById('windowSize');
const elWSV = document.getElementById('wsVal');
const btnReg = document.getElementById('btnReg');
const btnOff = document.getElementById('btnOff');
const chkGrid = document.getElementById('chkGrid');

function syncUI() {
  elWS.value = String(state.nIdx);
  elWSV.textContent = curN() + '×' + curN();
  btnReg.classList.toggle('active', !state.offset);
  btnOff.classList.toggle('active', state.offset);
  chkGrid.checked = state.grid;
  const p = panelId();
  letterLbl.div.innerHTML = p + ')';
  capLbl.div.innerHTML = CAPTION[p];
}

/* ---- tween machinery ----------------------------------------------------- */
let phase = 'idle', t0 = 0, gStart = 1, pending = null;
const ease = u => u * u * (3 - 2 * u);
const gTargetNow = () => (curN() === 1 ? 0 : 1);

function applyState() {
  syncUI();
  const N = curN(), off = state.offset && N > 1;
  if (N === state.curN && off === state.curOff) {
    pending = null;
    applyGridVisibility();
    gStart = gv; phase = 'open'; t0 = performance.now();
    return;
  }
  pending = { N, off };
  gStart = gv; phase = 'close'; t0 = performance.now();
}
function setState(n, off, grid) {
  state.nIdx = n; state.offset = off;
  if (grid !== undefined) state.grid = !!grid;
  applyState();
}

elWS.addEventListener('input', () => { state.nIdx = parseInt(elWS.value, 10); applyState(); });
btnReg.addEventListener('click', () => { state.offset = false; applyState(); });
btnOff.addEventListener('click', () => { state.offset = true; applyState(); });
chkGrid.addEventListener('change', () => {
  state.grid = chkGrid.checked;
  applyGridVisibility();
  syncUI();
});
document.querySelectorAll('[data-panel]').forEach(b => {
  b.addEventListener('click', () => {
    const s = PANEL_STATE[b.dataset.panel];
    setState(s.n, s.off, s.grid);
  });
});
document.getElementById('btnClear').addEventListener('click', () => { clearSelection(); updateTiles(gv); hidePopup(); });

/* ---- guided tour --------------------------------------------------------- */
const STEPS = [
  {
    t: 'f) 1×1 window — global attention',
    x: 'The whole photograph is a single window, so every token attends to every other token. Standard global self-attention: accurate, but quadratic in the number of patches.',
    n: 0, off: false
  },
  {
    t: 'd) 2×2 windows',
    x: 'Cutting the image into four windows confines attention to a quarter of the image at a time. Click a tile: its connections never cross the white gaps.',
    n: 1, off: false
  },
  {
    t: 'e) 2×2 offset windows',
    x: 'Shifting the same grid by half a window creates partial windows at the borders. Tokens split apart in panel d) now share a window (orange dots), letting information flow across the old boundaries.',
    n: 1, off: true
  },
  {
    t: 'b) 4×4 windows',
    x: 'Sixteen small windows: attention is strongly local and cheap, but each window is isolated from its neighbours.',
    n: 2, off: false
  },
  {
    t: 'c) 4×4 offset windows',
    x: 'Alternating this shifted partition with the regular one in successive layers is the Swin trick — locality is kept, yet receptive fields grow because every boundary is interior in the other layer.',
    n: 2, off: true
  }
