  if (!h) { clearSelection(); updateTiles(gv); return; }
  if (h.object.userData.dir !== undefined) {
    const cur = PANEL_ORDER.indexOf(panelId());
    const nxt = PANEL_ORDER[(cur + (h.object.userData.dir < 0 ? -1 : 1) + 6) % 6];
    const s = PANEL_STATE[nxt];
    setState(s.n, s.off, s.grid);
    return;
  }
  const t = tiles.find(q => q.mesh === h.object);
  if (t) selectTile(t);
});

/* ---- own animation loop: tile tween + marker pulse ----------------------- */
function tick(now) {
  requestAnimationFrame(tick);
  if (phase === 'close') {
    const u = Math.min(1, (now - t0) / 160);
    gv = gStart * (1 - ease(u));
    updateTiles(gv);
    if (u >= 1) {
      if (pending) { doBuild(pending.N, pending.off); pending = null; applyGridVisibility(); }
      gv = 0; updateTiles(0);
      phase = 'open'; t0 = now; gStart = 0;
    }
  } else if (phase === 'open') {
    const u = Math.min(1, (now - t0) / 260);
    gv = gStart + (gTargetNow() - gStart) * ease(u);
    updateTiles(gv);
    if (u >= 1) { gv = gTargetNow(); updateTiles(gv); phase = 'idle'; }
  }
  const p = 0.5 + 0.5 * Math.sin(now * 0.006);
  dotMat.size = 6 + 5 * p;
  dotMat.opacity = 0.45 + 0.5 * p;
}
requestAnimationFrame(tick);
