const muralTex = makeMural();

/* ---- shared materials ---------------------------------------------------- */
const tokenMat = new THREE.LineBasicMaterial({ color: 0x3B3B3B, transparent: true, opacity: 0.6 });
const hiMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.18, depthWrite: false });
