    const geo = new THREE.PlaneGeometry(1, 1);
    geo.setAttribute('uv', new THREE.Float32BufferAttribute([u0, v1, u1, v1, u0, v0, u1, v0], 2));
    const mat = new THREE.MeshBasicMaterial({ map: muralTex, side: THREE.DoubleSide });
