const muralTex = makeMural();

/* ---- shared materials ---------------------------------------------------- */
const tokenMat = new THREE.LineBasicMaterial({ color: 0x3B3B3B, transparent: true, opacity: 0.62 });
const hiMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.18, depthWrite: false });
const dotMat = new THREE.PointsMaterial({ color: 0xFF6A00, size: 7, sizeAttenuation: false, transparent: true, opacity: 0.9, depthTest: false });

/* ---- partition maths ----------------------------------------------------- */
function boundariesFor(N, off) {
  if (N <= 1) return [0, 1];
  const b = [];
  if (!off) { for (let i = 0; i <= N; i++) b.push(i / N); return b; }
  b.push(0);
  for (let i = 0; i < N; i++) b.push((2 * i + 1) / (2 * N));
  b.push(1);
  return b;
}
function winIndex(bs, c) {
  for (let k = 0; k < bs.length - 1; k++) if (c >= bs[k] && c < bs[k + 1]) return k;
  return bs.length - 2;
}
function tokensIn(u0, u1) {
  const a = [];
  for (let i = 0; i < TOK; i++) { const c = (i + 0.5) / TOK; if (c > u0 && c < u1) a.push(i); }
  return a;
}
function computeMarks(N, off) {
  const m = new Set();
  if (!off || N <= 1) return m;
  const reg = boundariesFor(N, false), ofs = boundariesFor(N, true);
  const c = i => (i + 0.5) / TOK;
  for (let j = 0; j < TOK; j++) for (let i = 0; i < TOK - 1; i++) {
    if (winIndex(reg, c(i)) !== winIndex(reg, c(i + 1)) && winIndex(ofs, c(i)) === winIndex(ofs, c(i + 1))) {
      m.add(i + ',' + j); m.add((i + 1) + ',' + j);
    }
  }
  for (let i = 0; i < TOK; i++) for (let j = 0; j < TOK - 1; j++) {
    if (winIndex(reg, c(j)) !== winIndex(reg, c(j + 1)) && winIndex(ofs, c(j)) === winIndex(ofs, c(j + 1))) {
      m.add(i + ',' + j); m.add(i + ',' + (j + 1));
    }
  }
  return m;
}
function costOf(N, off) {
  const bs = boundariesFor(N, off);
  let pairs = 0, wins = 0;
  for (let j = 0; j < bs.length - 1; j++) for (let i = 0; i < bs.length - 1; i++) {
    const n = tokensIn(bs[i], bs[i + 1]).length * tokensIn(bs[j], bs[j + 1]).length;
    pairs += n * (n - 1) / 2; wins++;
  }
  return { pairs, wins };
}

/* ---- tile construction --------------------------------------------------- */
let showMarks = false, showAttn = true;

function buildTiles(parent, N, off, grid, owner) {
  const bs = boundariesFor(N, off);
  const single = (bs.length - 1) === 1;
  const gap = single ? 0 : GAP;
  const marks = computeMarks(N, off);
  const out = [];
  for (let j = 0; j < bs.length - 1; j++) for (let i = 0; i < bs.length - 1; i++) {
    const u0 = bs[i], u1 = bs[i + 1], v0 = bs[j], v1 = bs[j + 1];
    const grp = new THREE.Group();

    const bmat = new THREE.MeshBasicMaterial({ color: 0x111111 });
    bmat.userData.perTile = true;
    const bord = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), bmat);
    bord.position.z = -0.004; grp.add(bord);

    const geo = new THREE.PlaneGeometry(1, 1);
    geo.setAttribute('uv', new THREE.Float32BufferAttribute([u0, v1, u1, v1, u0, v0, u1, v0], 2));
    const mat = new THREE.MeshBasicMaterial({ map: muralTex, side: THREE.DoubleSide });
    mat.userData.perTile = true;
    const mesh = new THREE.Mesh(geo, mat); grp.add(mesh);

    let tok = null;
    if (grid) {
      const seg = [];
      for (let k = 1; k < TOK; k++) {
        const u = k / TOK;
        if (u > u0 + 1e-6 && u < u1 - 1e-6) {
          const x = (u - u0) / (u1 - u0) - 0.5;
          seg.push(x, -0.5, 0.004, x, 0.5, 0.004);
        }
        const v = k / TOK;
        if (v > v0 + 1e-6 && v < v1 - 1e-6) {
          const y = (v - v0) / (v1 - v0) - 0.5;
          seg.push(-0.5, y, 0.004, 0.5, y, 0.004);
        }
      }
      if (seg.length) {
        const tg = new THREE.BufferGeometry();
        tg.setAttribute('position', new THREE.Float32BufferAttribute(seg, 3));
        tok = new THREE.LineSegments(tg, tokenMat);
        tok.renderOrder = 2; grp.add(tok);
      }
    }

    const hi = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), hiMat);
    hi.position.z = 0.008; hi.renderOrder = 4; hi.visible = false; grp.add(hi);

    let dots = null;
    const dp = [];
    for (const ti of tokensIn(u0, u1)) for (const tj of tokensIn(v0, v1)) {
      if (marks.has(ti + ',' + tj)) {
        dp.push(((ti + 0.5) / TOK - u0) / (u1 - u0) - 0.5,
          ((tj + 0.5) / TOK - v0) / (v1 - v0) - 0.5, 0.012);
      }
    }
    if (dp.length) {
      const dg = new THREE.BufferGeometry();
      dg.setAttribute('position', new THREE.Float32BufferAttribute(dp, 3));
      dots = new THREE.Points(dg, dotMat);
      dots.renderOrder = 6; dots.visible = showMarks; grp.add(dots);
    }

    parent.add(grp);
    out.push({
      group: grp, mesh, bord, hi, tok, dots, attn: null, owner,
      u0, u1, v0, v1, gap,
      w0: (u1 - u0) * PW, h0: (v1 - v0) * PH,
      cx: ((u0 + u1) / 2 - 0.5) * PW, cy: ((v0 + v1) / 2 - 0.5) * PH
    });
  }
  return out;
}

let sel = null;
function relayout(list, gv) {
  for (const t of list) {
    const w = Math.max(0.02, t.w0 - t.gap * gv);
    const h = Math.max(0.02, t.h0 - t.gap * gv);
    t.group.scale.set(w, h, 1);
    t.group.position.set(t.cx, t.cy, 0);
    const bb = (t === sel) ? 2.8 * BORD : BORD;
    t.bord.scale.set(1 + 2 * bb / w, 1 + 2 * bb / h, 1);
  }
}

/* ---- the six-panel filmstrip -------------------------------------------- */
const PANELS = [
