for (const p of PANELS) {
  const g = new THREE.Group();
  g.position.x = p.x;
  stripRoot.add(g);
  p.group = g;
  p.tiles = buildTiles(g, p.N, p.off, p.grid, p);
  relayout(p.tiles, 1);
}
const allStripTiles = PANELS.flatMap(p => p.tiles);

/* ---- ellipsis dots between c|d and e|f ---------------------------------- */
const dotsGroup = new THREE.Group();
scene.add(dotsGroup);
const ellipMat = new THREE.MeshBasicMaterial({ color: 0x222222 });
const ellipMeshes = [];
[['c', 'd'], ['e', 'f']].forEach(([l, r]) => {
  const pl = PANELS.find(p => p.id === l), pr = PANELS.find(p => p.id === r);
  const mid = (pl.x + pr.x) / 2;
  for (let k = -1; k <= 1; k++) {
