/* ---- sandbox panel (built, added only in sandbox mode) ------------------- */
const sandRoot = tiltGroup(PH, LEAN);
const sandPanel = { id: 'sand', N: 4, off: false, grid: true, group: new THREE.Group(), tiles: [] };
sandRoot.add(sandPanel.group);
function buildSandbox() {
  for (const t of sandPanel.tiles) {
    sandPanel.group.remove(t.group);
    t.group.traverse(o => {
      o.geometry?.dispose?.();
      const m = o.material;
      if (m && m.userData && m.userData.perTile) m.dispose();
    });
  }
  sandPanel.tiles = buildTiles(sandPanel.group, sandPanel.N, sandPanel.off, sandPanel.grid, sandPanel);
  relayout(sandPanel.tiles, gv);
}
let gv = 1;
buildSandbox();

/* ---- camera framing ------------------------------------------------------ */
const OBL = { projection: 'oblique', obliqueAngleDeg: 45, depthScale: 0.5, rollDeg: 0 };
function aspectNow() { return (canvas.clientWidth || 1) / (canvas.clientHeight || 1); }
function frameStrip() {
  setCameraView({ ...OBL, heightFraction: 0.92, target: [0, 0, 0] });
}
function frameSandbox() {
  setCameraView({ ...OBL, heightFraction: 0.82, target: [0, 0, 0] });
}
function focusPanel(id) {
  const p = PANELS.find(q => q.id === id);
  const zh = 6 * 0.80 / (PH * 1.20);
  const zw = 6 * aspectNow() * 0.80 / (PW + 2 * LEAN + 0.55);
  setCameraView({ ...OBL, zoom: Math.min(zh, zw), target: [p.x, 0, 0], heightFraction: 0.8 });
}

frameStrip();

/* ---- labels: letter (large) + caption (small) for EVERY panel ------------ */
const stripLabels = [];
