showLabels(true);

/* ---- selection + attention ---------------------------------------------- */
const selInfo = document.getElementById('selInfo');
function relayoutAll() {
  for (const p of PANELS) relayout(p.tiles, 1);
  relayout(sandPanel.tiles, gv);
}
function clearSelection(quiet) {
  if (sel) {
    sel.hi.visible = false;
    sel.bord.material.color.setHex(0x111111);
    if (sel.attn) { sel.group.remove(sel.attn); sel.attn.geometry.dispose(); sel.attn.material.dispose(); sel.attn = null; }
    for (const o of sel.owner.tiles) o.mesh.material.color.setHex(0xffffff);
    sel = null;
  }
  relayoutAll();
  if (!quiet) selInfo.textContent = 'Click any window to compute the self-attention inside it.';
}
function selectTile(t) {
  clearSelection(true);
  sel = t;
  t.hi.visible = true;
  t.bord.material.color.setHex(0xFFD24A);
  for (const o of t.owner.tiles) o.mesh.material.color.setHex(o === t ? 0xffffff : 0x9a9a9a);

  const xs = tokensIn(t.u0, t.u1).map(i => ((i + 0.5) / TOK - t.u0) / (t.u1 - t.u0) - 0.5);
  const ys = tokensIn(t.v0, t.v1).map(j => ((j + 0.5) / TOK - t.v0) / (t.v1 - t.v0) - 0.5);
  const P = [];
  for (const y of ys) for (const x of xs) P.push([x, y]);
  const pairs = P.length * (P.length - 1) / 2;

  if (showAttn && pairs > 0) {
    const pos = [];
    for (let a = 0; a < P.length; a++) for (let b = a + 1; b < P.length; b++) {
      pos.push(P[a][0], P[a][1], 0.009, P[b][0], P[b][1], 0.009);
    }
    const op = pairs <= 50 ? 0.34 : pairs <= 200 ? 0.2 : pairs <= 700 ? 0.11 : 0.06;
    const gm = new THREE.BufferGeometry();
    gm.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    const mm = new THREE.LineBasicMaterial({ color: 0x1E6FE0, transparent: true, opacity: op, depthTest: false });
    mm.userData.perTile = true;
    const ln = new THREE.LineSegments(gm, mm);
    ln.renderOrder = 7;
    t.group.add(ln); t.attn = ln;
  }
  relayoutAll();

  const tot = costOf(t.owner.N, t.owner.off);
  const pid = t.owner.id === 'sand' ? 'sandbox panel' : 'panel ' + t.owner.id + ')';
  selInfo.innerHTML = `Selected window: <b>${xs.length}×${ys.length}</b> tokens → <b>${pairs}</b> attention pairs.<br>
    Whole ${pid}: ${tot.wins} windows, <b>${tot.pairs}</b> pairs (global attention would need 2016).`;
  showPopup('Self-attention inside one window',
    `This window holds ${P.length} of the 64 tokens, so it costs ${pairs} attention pairs. ` +
    `Links never cross the white gaps: in this layer neighbouring windows cannot exchange information — ` +
    `which is exactly why the next layer uses the shifted partition.`);
}

/* ---- cost table ---------------------------------------------------------- */
{
  const rows = PANELS.map(p => {
