/* ---- UI wiring ----------------------------------------------------------- */
const btnStrip = document.getElementById('btnStrip');
const btnSand = document.getElementById('btnSand');
const stripUI = document.getElementById('stripUI');
const sandUI = document.getElementById('sandUI');
const btnAll = document.getElementById('btnAll');
const focusBtns = Array.from(document.querySelectorAll('[data-focus]'));
let mode = 'strip';

function setMode(m) {
  mode = m;
  clearSelection(true);
  btnStrip.classList.toggle('active', m === 'strip');
  btnSand.classList.toggle('active', m === 'sand');
  stripUI.style.display = m === 'strip' ? '' : 'none';
  sandUI.style.display = m === 'strip' ? 'none' : 'flex';
  if (m === 'strip') {
    scene.remove(sandRoot); scene.add(stripRoot); scene.add(dotsGroup);
    showLabels(true); frameStrip();
    btnAll.classList.add('active'); focusBtns.forEach(b => b.classList.remove('active'));
  } else {
    scene.remove(stripRoot); scene.remove(dotsGroup); scene.add(sandRoot);
    showLabels(false); frameSandbox();
  }
  selInfo.textContent = 'Click any window to compute the self-attention inside it.';
}
btnStrip.addEventListener('click', () => setMode('strip'));
btnSand.addEventListener('click', () => setMode('sand'));

btnAll.addEventListener('click', () => {
  frameStrip();
  btnAll.classList.add('active'); focusBtns.forEach(b => b.classList.remove('active'));
});
focusBtns.forEach(b => b.addEventListener('click', () => {
