  focusPanel(b.dataset.focus);
  btnAll.classList.remove('active');
  focusBtns.forEach(o => o.classList.toggle('active', o === b));
}));

const chkAttn = document.getElementById('chkAttn');
const chkMarks = document.getElementById('chkMarks');
chkAttn.addEventListener('change', () => {
