/* ---- sandbox controls ---------------------------------------------------- */
const elWS = document.getElementById('windowSize');
const elWSV = document.getElementById('wsVal');
const btnReg = document.getElementById('btnReg');
const btnOff = document.getElementById('btnOff');
const chkGrid = document.getElementById('chkGrid');
let phase = 'idle', t0 = 0, gStart = 1, pending = null;
const ease = u => u * u * (3 - 2 * u);
const gTarget = () => (sandPanel.N <= 1 ? 0 : 1);

function sandChanged() {
  elWSV.textContent = sandPanel.N + '×' + sandPanel.N;
  btnReg.classList.toggle('active', !sandPanel.off);
  btnOff.classList.toggle('active', sandPanel.off);
  chkGrid.checked = sandPanel.grid;
  const pm = PANELS.find(p => p.N === sandPanel.N && p.off === sandPanel.off && p.grid === sandPanel.grid);
  sandLetter.div.innerHTML = pm ? pm.id + ')' : '·';
  sandCap.div.innerHTML = sandPanel.N + '×' + sandPanel.N + (sandPanel.off ? ' offset<br>' : '<br>') +
    (sandPanel.N > 1 ? 'windows' : 'window');
  clearSelection(true);
  pending = true; gStart = gv; phase = 'close'; t0 = performance.now();
}
elWS.addEventListener('input', () => { sandPanel.N = parseInt(elWS.value, 10); sandChanged(); });
btnReg.addEventListener('click', () => { sandPanel.off = false; sandChanged(); });
btnOff.addEventListener('click', () => { sandPanel.off = true; sandChanged(); });
chkGrid.addEventListener('change', () => { sandPanel.grid = chkGrid.checked; sandChanged(); });
document.getElementById('btnClear').addEventListener('click', () => { clearSelection(); hidePopup(); });

/* ---- guided tour --------------------------------------------------------- */
const STEPS = [
  { p: 'a', t: 'a) the input image', x: 'The photograph is split into 8×8 = 64 patch tokens. Plain global self-attention relates all of them: 2016 pairs.' },
  { p: 'b', t: 'b) 4×4 windows', x: '16 windows of 2×2 tokens. Attention runs only inside a window — 16×6 = 96 pairs — cheap, but the windows are isolated from each other.' },
  { p: 'c', t: 'c) 4×4 offset windows', x: 'The same grid shifted by half a window; partial windows appear at the border. Boundaries that separated tokens in b) are now interior, so information crosses them.' },
  { p: 'd', t: 'd) 2×2 windows', x: '4 windows of 4×4 = 16 tokens, 480 pairs: a larger receptive field per layer at a higher cost.' },
  { p: 'e', t: 'e) 2×2 offset windows', x: 'Shifted again. Alternating the regular and the shifted partition in successive layers is the Swin transformer trick.' },
  { p: 'f', t: 'f) 1×1 window', x: 'One window covering everything — ordinary global attention, 2016 pairs, quadratic in the number of tokens.' }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  stepTitle.textContent = s.t;
  stepText.textContent = s.x;
  if (mode !== 'strip') setMode('strip');
  focusPanel(s.p);
  btnAll.classList.remove('active');
  focusBtns.forEach(o => o.classList.toggle('active', o.dataset.focus === s.p));
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
let playT = null;
const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  if (playT) { clearInterval(playT); playT = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); }
  else {
    btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
    goToStep(stepIdx + 1);
    playT = setInterval(() => goToStep(stepIdx + 1), 3600);
  }
});
stepTitle.textContent = 'The whole figure';
stepText.textContent = 'Six partitions of the same photograph, from 4×4 windows down to a single global window. Press ▶ to walk through them, or click a window to see the attention inside it.';

/* ---- picking (oblique-aware ray) ---------------------------------------- */
const rc = new THREE.Raycaster();
function pickList() {
  return (mode === 'strip' ? allStripTiles : sandPanel.tiles).map(t => t.mesh)
    .concat(mode === 'strip' ? ellipMeshes : []);
}
function pick(ev) {
  const r = canvas.getBoundingClientRect();
  const nx = ((ev.clientX - r.left) / r.width) * 2 - 1;
  const ny = -((ev.clientY - r.top) / r.height) * 2 + 1;
  const a = new THREE.Vector3(nx, ny, -1).unproject(camera);
  const b = new THREE.Vector3(nx, ny, 1).unproject(camera);
  rc.set(a, b.sub(a).normalize());
  const hits = rc.intersectObjects(pickList(), false);
  return hits.length ? hits[0] : null;
}
function tileOf(obj) {
  const list = mode === 'strip' ? allStripTiles : sandPanel.tiles;
  return list.find(t => t.mesh === obj) || null;
}
let downX = 0, downY = 0, moved = 0;
canvas.addEventListener('pointerdown', e => { downX = e.clientX; downY = e.clientY; moved = 0; });
canvas.addEventListener('pointermove', e => {
  moved = Math.abs(e.clientX - downX) + Math.abs(e.clientY - downY);
  const h = pick(e);
  if (h) {
    if (h.object.userData.jump) showTooltip('the strip continues → jump to panel ' + h.object.userData.jump + ')', e);
    else {
      const t = tileOf(h.object);
      showTooltip(t && t === sel ? 'Selected window — click another one'
        : 'Click: self-attention inside this window', e);
    }
    canvas.style.cursor = 'pointer';
  } else { hideTooltip(); canvas.style.cursor = 'grab'; }
});
canvas.addEventListener('click', e => {
  if (moved > 5) return;
  const h = pick(e);
  if (!h) { clearSelection(); return; }
  if (h.object.userData.jump) {
    const id = h.object.userData.jump;
    focusPanel(id);
    btnAll.classList.remove('active');
    focusBtns.forEach(o => o.classList.toggle('active', o.dataset.focus === id));
    return;
  }
  const t = tileOf(h.object);
  if (t) selectTile(t);
});

/* ---- own loop: sandbox gap tween + marker pulse -------------------------- */
function tick(now) {
  requestAnimationFrame(tick);
  if (phase === 'close') {
    const u = Math.min(1, (now - t0) / 150);
    gv = gStart * (1 - ease(u));
    relayout(sandPanel.tiles, gv);
    if (u >= 1) {
      if (pending) { buildSandbox(); pending = null; }
      gv = 0; relayout(sandPanel.tiles, 0);
      phase = 'open'; t0 = now; gStart = 0;
    }
  } else if (phase === 'open') {
    const u = Math.min(1, (now - t0) / 250);
    gv = gStart + (gTarget() - gStart) * ease(u);
    relayout(sandPanel.tiles, gv);
    if (u >= 1) { gv = gTarget(); relayout(sandPanel.tiles, gv); phase = 'idle'; }
  }
  if (showMarks) {
    const p = 0.5 + 0.5 * Math.sin(now * 0.006);
    dotMat.size = 5 + 4.5 * p;
    dotMat.opacity = 0.45 + 0.5 * p;
  }
}
requestAnimationFrame(tick);

/* ---- keep the strip framed when the canvas is resized -------------------- */
let _rT = null;
new ResizeObserver(() => {
  clearTimeout(_rT);
  _rT = setTimeout(() => {
    if (mode === 'strip' && btnAll.classList.contains('active')) frameStrip();
  }, 60);
}).observe(canvas);
